namespace pixc {

// ---------------------------------------------------------------------------------------------
// MQTT topic routing
// ---------------------------------------------------------------------------------------------

enum class Topic : uint8_t { None, Cfg, Reset, Ota };

// Classify a topic as delivered to Usermod::onMqttMessage().
//
// WLED's MQTT handler (wled00/mqtt.cpp, onMqttMessage) strips `mqttDeviceTopic` before calling
// the usermods, so a subscription to `epixc/v1/d/<mac>/cfg` arrives here as "/cfg". A topic that
// did NOT start with the device prefix arrives unstripped. Both forms are accepted, and each is
// compared EXACTLY: "/ota/progress" is a topic this device publishes and must never be mistaken
// for an OTA command, and "/cfgX" is nothing.
//
// `deviceTopic` may be null or empty, in which case only the stripped form can match.
inline Topic classifyTopic(const char* topic, const char* deviceTopic) {
  if (topic == nullptr) return Topic::None;
  const char* rest = topic;
  const size_t baseLen = deviceTopic ? strlen(deviceTopic) : 0;
  if (baseLen > 0 && strncmp(topic, deviceTopic, baseLen) == 0) rest = topic + baseLen;
  if (strcmp(rest, "/cfg") == 0) return Topic::Cfg;
  if (strcmp(rest, "/reset") == 0) return Topic::Reset;
  if (strcmp(rest, "/ota") == 0) return Topic::Ota;
  return Topic::None;
}

}  // namespace pixc
